<?php
 namespace Pterodactyl\Models\Dezerx; use Pterodactyl\Models\User; use Pterodactyl\Models\Model; use Illuminate\Database\Eloquent\Relations\BelongsTo; class ImportCredential extends Model { public const RESOURCE_NAME = 'import_credential'; public const AUTH = ['password', 'key']; public const MAX_PER_USER = 25; protected $table = 'dezerx_import_credentials'; protected $guarded = ['id']; protected $casts = [ 'user_id' => 'int', 'secret' => 'encrypted', 'passphrase' => 'encrypted', 'last_used_at' => 'datetime', ]; protected $hidden = ['secret', 'passphrase']; public static array $validationRules = [ 'user_id' => 'required|int|exists:users,id', 'label' => 'required|string|max:60', 'username' => 'required|string|max:120', 'auth' => 'required|string|in:password,key', 'secret' => 'required|string|max:32768', 'passphrase' => 'nullable|string|max:120', ]; public function toClient(): array { return [ 'id' => (string) $this->id, 'label' => (string) $this->label, 'username' => (string) $this->username, 'auth' => (string) $this->auth, 'lastUsedAt' => $this->last_used_at?->toAtomString(), ]; } public function user(): BelongsTo { return $this->belongsTo(User::class); } } 